var handler = new Logging("outer") { InnerHandler = new Logging("inner") { InnerHandler = new Stub() } };
using var client = new HttpClient(handler);
await client.GetAsync("http://example.test/");

class Logging(string name) : DelegatingHandler
{
    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage req, CancellationToken ct)
    {
        Console.WriteLine($"{name} request");
        var res = await base.SendAsync(req, ct);
        Console.WriteLine($"{name} response");
        return res;
    }
}

class Stub : HttpMessageHandler
{
